const listaReclamos = items.map(item => {
  const d = item.json || {};
  const nroOt = d.ot_nro_ot || d.ot_id || 'S/N';
  const tarea = d.ot_tarea ? d.ot_tarea.trim() : 'Sin descripción';
  const estado = d.aux_et_nombre || 'En Proceso';
