try {
  const items = $input.all().map(item => item.json).filter(j => j && j.Servicio != null);

  // Diccionario por defecto en caso de que en la BD el JOIN devuelva nulo
  const descripcionesFallback = {
    1: "En Proceso",
    2: "Activo",
    3: "Suspendido",
    4: "Inactivo"
  };

  let resultadoValidacion = {
    permite_reclamo: true,
    servicios: {}
  };

  items.forEach(item => {
    const servicio = item.Servicio.toLowerCase(); // "energia", "agua", "internet"
    const activoVal = parseInt(item.Activo);
    const codEstado = parseInt(item.CodEstado);
    const causaBaja = item.CausaBaja;
    const descEstado = item.EstadoDescripcion || descripcionesFallback[codEstado] || "Desconocido";

    // CONDICIÓN DE HABILITACIÓN:
    // Debe tener Activo === 1 Y CodEstado === 2 (Activo)
    const esValido = (activoVal === 1 && codEstado === 2);

    // Definición del motivo y mensaje visual para Typebot
    let mensajeExplicativo = "";

    if (esValido) {
      mensajeExplicativo = "🟢 Suministro Activo y habilitado para reclamos.";
    } else if (codEstado === 3) {
      mensajeExplicativo = "🚫 Tu suministro se encuentra **SUSPENDIDO**. No es posible ingresar reclamos técnicos en este momento.";
    } else if (codEstado === 4 || activoVal === 0) {
      mensajeExplicativo = "🔴 Tu suministro se encuentra **INACTIVO**. Por favor, contactate con atención al cliente para regularizar la alta.";
    } else if (codEstado === 1) {
      mensajeExplicativo = "⏳ Tu suministro se encuentra **EN PROCESO** de alta/trámite. Todavía no se encuentra habilitado para reclamos.";
    } else {
      mensajeExplicativo = `⚠️ El suministro se encuentra en estado: **${descEstado}**.`;
    }

    resultadoValidacion.servicios[servicio] = {
      codigo: item.Codigo,
      activo: activoVal,
      cod_estado: codEstado,
      estado_descripcion: descEstado,
      causaBaja: causaBaja,
      esta_ok: esValido,
      mensaje_estado: mensajeExplicativo
    };
  });

  return [{ json: resultadoValidacion }];

} catch (e) {
  return [{
    json: {
      permite_reclamo: false,
      mensaje_bloqueo: "Error al procesar la validación de estados.",
      servicios: {}
    }
  }];
}

const inputData = $input.first().json;

// 1. Obtenemos el texto bruto del body
let rawBody = '';
if (inputData.query && inputData.query.body) {
  rawBody = typeof inputData.query.body === 'string' ? inputData.query.body : JSON.stringify(inputData.query.body);
} else if (inputData.body) {
  rawBody = typeof inputData.body === 'string' ? inputData.body : JSON.stringify(inputData.body);
}

let socio = '';
let codigo = '';
let domicilio = '';

// 2. Intentamos parsear como JSON normal
try {
  const parsed = JSON.parse(rawBody);
  socio = parsed.socio || '';
  codigo = parsed.codigo || parsed.user_id || '';
  domicilio = parsed.domicilio || '';
} catch (e) {
  // 3. Si el JSON viene mal construido/sin comas, extraemos los datos con Expresiones Regulares (Regex)
  const socioMatch = rawBody.match(/"socio"\s*:\s*"([^"]+)"/);
  const codigoMatch = rawBody.match(/"codigo"\s*:\s*"([^"]+)"/) || rawBody.match(/"user_id"\s*:\s*"([^"]+)"/);
  const domMatch = rawBody.match(/"domicilio"\s*:\s*"([^"]+)"/);

  if (socioMatch) socio = socioMatch[1];
  if (codigoMatch) codigo = codigoMatch[1];
  if (domMatch) domicilio = domMatch[1];
}

// 4. Limpiamos los paréntesis del domicilio
if (typeof domicilio === 'string' && domicilio.includes('(')) {
  domicilio = domicilio.split('(')[0];
}

// 5. Validación (H-01)
const socioLimpio = String(socio).trim().replace(/[\s.\-]/g, '');
if (!/^\d{1,15}$/.test(socioLimpio)) {
  throw new Error('Entrada inválida en el campo "socio"');
}
let domicilioSeguro = String(domicilio).trim().toUpperCase().slice(0, 200);
domicilioSeguro = domicilioSeguro.replace(/'/g, "''");

return [{
  json: {
    socio: socioLimpio,
    codigo: String(codigo).trim(),
    domicilio_limpio: domicilioSeguro
  }
}];

