// Validación del reclamo (H-01) y domicilio para buscar el medidor (H-08)
const body = $input.first().json.body || {};

const cuenta = String(body.cuenta ?? '').trim().replace(/[\s.\-]/g, '');
if (!/^\d{1,15}$/.test(cuenta)) {
  throw new Error('Entrada inválida en el campo "cuenta"');
}

let domicilio = String(body.domicilio ?? '');
if (domicilio.includes('(')) domicilio = domicilio.split('(')[0];
domicilio = domicilio.trim().toUpperCase().slice(0, 200).replace(/'/g, "''");

return [{ json: { cuenta, domicilio_limpio: domicilio } }];

// Respuesta para Typebot (H-12): confirma el alta y devuelve el N° de OT
const fila = $input.first()?.json || {};
const nro = fila.ot_nro_ot ?? null;

return [{
  json: {
    ok: nro !== null,
    nro_ot: nro
  }
}];

// Validación de entrada (H-01): solo dígitos en números, comillas escapadas en texto
const NUMERICOS = ["nro_socio"];
const TEXTOS    = [];
const MOTOR     = 'mysql';
const LARGO_MIN = {};

const entrada = $input.first().json;
const body = { ...(entrada.body || {}) };

for (const campo of NUMERICOS) {
  const limpio = String(body[campo] ?? '').trim().replace(/[\s.\-()+]/g, '');
  const minimo = LARGO_MIN[campo] || 1;
  if (!/^\d+$/.test(limpio) || limpio.length < minimo || limpio.length > 15) {
    throw new Error(`Entrada inválida en el campo "${campo}"`);
  }
  body[campo] = limpio;
}

for (const campo of TEXTOS) {
  let texto = String(body[campo] ?? '').trim().slice(0, 200);
  if (MOTOR === 'mysql') texto = texto.replace(/\\/g, '\\\\');
  body[campo] = texto.replace(/'/g, "''");
}

return [{ json: { ...entrada, body } }];
